builder.Services.AddAuthentication(options =>
{
    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
})
.AddCookie()
.AddSaml2(options =>
{
    options.SPOptions.EntityId = new EntityId("https://app.example.com");
    options.SPOptions.ReturnUrl = new Uri("https://app.example.com/");

    var identityProvider = options.IdentityProviders[
        "https://login.idp.com"]
        = new IdentityProvider(new EntityId("https://login.idp.com"), options.SPOptions)
    {
        LoadMetadata = true,
        MetadataLocation = "https://login.idp.com/federationmetadata/2007-06/federationmetadata.xml"
    };
});

app.MapGet("/account/profile", async (HttpContext ctx, AppDbContext db) =>
{
    var externalId = ctx.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
    var email = ctx.User.FindFirst(ClaimTypes.Email)?.Value;

    var user = await db.Users
        .FirstOrDefaultAsync(u => u.ExternalId == externalId);

    if (user == null)
    {
        user = new User
        {
            ExternalId = externalId,
            Email = email,
            DisplayName = ctx.User.Identity.Name,
            CreatedAt = DateTime.UtcNow
        };
        db.Users.Add(user);
        await db.SaveChangesAsync();
    }

    return Results.Ok(new { user.Id, user.Email, user.DisplayName });
}).RequireAuthorization();
